1	package com.example.starter.service;
2	
3	import com.example.starter.domain.AdjustmentTask;
4	import com.example.starter.domain.Assessment;
5	import com.example.starter.domain.HeatingUnit;
6	import com.example.starter.domain.UnsealOrder;
7	import com.example.starter.domain.Valve;
8	import com.example.starter.domain.ValveVersion;
9	import com.example.starter.repository.AdjustmentTaskRepository;
10	import com.example.starter.repository.AssessmentRepository;
11	import com.example.starter.repository.StationRepository;
12	import com.example.starter.repository.UnitRepository;
13	import com.example.starter.repository.UnsealOrderRepository;
14	import com.example.starter.repository.UnsealQuotaUsageRepository;
15	import com.example.starter.repository.ValveRepository;
16	import com.example.starter.repository.ValveSealRepository;
17	import com.example.starter.repository.ValveVersionRepository;
18	import com.fasterxml.jackson.databind.ObjectMapper;
19	import org.springframework.dao.DuplicateKeyException;
20	import org.springframework.stereotype.Service;
21	import org.springframework.transaction.annotation.Transactional;
22	
23	import java.math.BigDecimal;
24	import java.nio.charset.StandardCharsets;
25	import java.security.MessageDigest;
26	import java.security.NoSuchAlgorithmException;
27	import java.time.Clock;
28	import java.time.Duration;
29	import java.time.Instant;
30	import java.util.HexFormat;
31	import java.util.List;
32	
33	/**
34	 * 调节流转核心服务：初调节/再调节指令受理、效果评估、归档终态。
35	 */
36	@Service
37	public class AdjustmentService {
38	
39	    /** 单次步进幅度上限：不超过 10%（恰 10% 合法）。 */
40	    public static final BigDecimal MAX_STEP_PERCENT = new BigDecimal("10");
41	    /** 稳定期：调节后须稳定 4 小时再评估（恰满 4 小时允许评估）。 */
42	    public static final Duration STABILIZATION = Duration.ofHours(4);
43	    /** 24 小时（UTC）窗口内单单元最多调节 3 次（恰 3 次合法），超出转人工复核。 */
44	    public static final int MAX_ADJUSTMENTS_PER_24H = 3;
45	    /** 24 小时窗口长度。 */
46	    public static final Duration ADJUSTMENT_WINDOW = Duration.ofHours(24);
47	
48	    private final StationRepository stationRepository;
49	    private final UnitRepository unitRepository;
50	    private final ValveRepository valveRepository;
51	    private final ValveVersionRepository versionRepository;
52	    private final AdjustmentTaskRepository taskRepository;
53	    private final AssessmentRepository assessmentRepository;
54	    private final ValveSealRepository sealRepository;
55	    private final UnsealOrderRepository unsealRepository;
56	    private final UnsealQuotaUsageRepository usageRepository;
57	    private final BalanceService balanceService;
58	    private final ObjectMapper objectMapper;
59	    private final Clock clock;
60	
61	    public AdjustmentService(StationRepository stationRepository,
62	                             UnitRepository unitRepository,
63	                             ValveRepository valveRepository,
64	                             ValveVersionRepository versionRepository,
65	                             AdjustmentTaskRepository taskRepository,
66	                             AssessmentRepository assessmentRepository,
67	                             ValveSealRepository sealRepository,
68	                             UnsealOrderRepository unsealRepository,
69	                             UnsealQuotaUsageRepository usageRepository,
70	                             BalanceService balanceService,
71	                             ObjectMapper objectMapper,
72	                             Clock clock) {
73	        this.stationRepository = stationRepository;
74	        this.unitRepository = unitRepository;
75	        this.valveRepository = valveRepository;
76	        this.versionRepository = versionRepository;
77	        this.taskRepository = taskRepository;
78	        this.assessmentRepository = assessmentRepository;
79	        this.sealRepository = sealRepository;
80	        this.unsealRepository = unsealRepository;
81	        this.usageRepository = usageRepository;
82	        this.balanceService = balanceService;
83	        this.objectMapper = objectMapper;
84	        this.clock = clock;
85	    }
86	
87	    /**
88	     * 下达调节令：幂等受理，站内同时刻只允许一个执行中任务；
89	     * 阀门开度写入与版本记录在同一事务内完成。
90	     *
91	     * @param stationId   换热站 ID
92	     * @param requestId   客户端幂等键
93	     * @param unitId      目标单元 ID
94	     * @param stepPercent 步进幅度，单位 %，0 &lt; step &le; 10
95	     * @return 已受理（或幂等重放的首次）任务
96	     */
97	    @Transactional
98	    public AdjustmentTask issueAdjustment(long stationId, String requestId, long unitId,
99	                                          BigDecimal stepPercent) {
100	        String fingerprint = fingerprint("ADJ", requestId, String.valueOf(stationId),
101	                String.valueOf(unitId), stepPercent.stripTrailingZeros().toPlainString());
102	        var existing = taskRepository.findByRequestId(requestId);
103	        if (existing.isPresent()) {
104	            return replayOrConflict(existing.get(), fingerprint);
105	        }
106	        if (stepPercent == null || stepPercent.compareTo(BigDecimal.ZERO) <= 0
107	                || stepPercent.compareTo(MAX_STEP_PERCENT) > 0) {
108	            throw new UnprocessableException("单次步进幅度须为 (0, 10]%，当前: " + stepPercent);
109	        }
110	        // 行级锁串行化同一换热站的任务受理，保证并发下唯一受理。
111	        stationRepository.lockById(stationId)
112	                .orElseThrow(() -> new NotFoundException("换热站不存在: stationId=" + stationId));
113	        // 持锁后重查幂等键：并发下同键请求在前序事务提交后按重放处理。
114	        var existingAfterLock = taskRepository.findByRequestId(requestId);
115	        if (existingAfterLock.isPresent()) {
116	            return replayOrConflict(existingAfterLock.get(), fingerprint);
117	        }
118	        HeatingUnit unit = unitRepository.findById(unitId)
119	                .filter(u -> u.stationId() == stationId)
120	                .orElseThrow(() -> new NotFoundException(
121	                        "单元不存在或不属于该换热站: unitId=" + unitId));
122	        Valve valve = valveRepository.findByUnitId(unitId)
123	                .orElseThrow(() -> new NotFoundException("单元未配置阀门: unitId=" + unitId));
124	        // 行锁串行化铅封登记/复封与本调节令（锁顺序：station → valve → unseal）。
125	        valve = valveRepository.lockById(valve.id()).orElseThrow();
126	        // 完整铅封下新的调节令必须拒绝；无台账的旧阀门仍按原规则工作。
127	        if (sealRepository.findActiveByValveId(valve.id()).isPresent()) {
128	            throw new UnprocessableException(
129	                    "阀门处于完整铅封状态，新的调节令被拒绝，须先临时解封: valveId=" + valve.id());
130	        }
131	        if (taskRepository.existsActiveByStationId(stationId)) {
132	            throw new ConflictException("换热站存在执行中的调节任务，并发下达唯一受理: stationId=" + stationId);
133	        }
134	        Instant now = clock.instant();
135	        int executed = taskRepository.countExecutedSince(unitId, now.minus(ADJUSTMENT_WINDOW));
136	        if (executed >= MAX_ADJUSTMENTS_PER_24H) {
137	            AdjustmentTask review = new AdjustmentTask(0, stationId, unitId, requestId, fingerprint,
138	                    null, null, null, null, AdjustmentTask.TaskStatus.MANUAL_REVIEW,
139	                    null, null, null, now);
140	            return taskRepository.findById(taskRepository.insert(review)).orElseThrow();
141	        }
142	        BalanceService.BalanceView balance = balanceService.evaluateBalance(stationId, now);
143	        AdjustmentTask.ImbalanceType classification = balance.units().stream()
144	                .filter(u -> u.unitId() == unit.id())
145	                .map(BalanceService.UnitTemperature::classification)
146	                .findFirst()
147	                .orElseThrow(() -> new UnprocessableException(
148	                        "单元无温度数据或未失衡，无法判定调节方向: unitId=" + unitId));
149	        BigDecimal oldOpening = valve.openingPercent();
150	        BigDecimal newOpening = classification == AdjustmentTask.ImbalanceType.UNDERFLOW
151	                ? oldOpening.add(stepPercent) : oldOpening.subtract(stepPercent);
152	        if (newOpening.compareTo(BigDecimal.ZERO) < 0
153	                || newOpening.compareTo(new BigDecimal("100")) > 0) {
154	            throw new UnprocessableException("调节后开度越界 [0,100]%: " + newOpening);
155	        }
156	        AdjustmentTask task = new AdjustmentTask(0, stationId, unitId, requestId, fingerprint,
157	                classification, stepPercent, oldOpening, newOpening,
158	                AdjustmentTask.TaskStatus.EXECUTING, now, null, null, now);
159	        long taskId;
160	        try {
161	            taskId = taskRepository.insert(task);
162	        } catch (DuplicateKeyException e) {
163	            // 并发下同键插入：唯一约束保证只受理一次，重放首个结果。
164	            return taskRepository.findByRequestId(requestId)
165	                    .map(t -> replayOrConflict(t, fingerprint))
166	                    .orElseThrow(() -> e);
167	        }
168	        // 开度写入与版本记录同事务提交，任一失败整体回滚。
169	        valveRepository.updateOpening(valve.id(), newOpening, now);
170	        versionRepository.insert(valve.id(), taskId,
171	                versionRepository.maxVersionNo(valve.id()) + 1, oldOpening, newOpening, now);
172	        return taskRepository.findById(taskId).orElseThrow();
173	    }
174	
175	    /**
176	     * 受控调节：在临时解封窗口与额度内下达调节令，仍遵守原 10% 步进、
177	     * 24 小时最多 3 次及站内唯一执行中任务规则。
178	     * 事务内重查解封未撤销、在窗内（半开区间，恰到终点失效）、额度足够及版本一致，
179	     * 再原子更新开度、写版本并消费一次额度；失败不消费，重复同键不消费两次。
180	     *
181	     * @param unsealId       解封单 ID
182	     * @param requestId      客户端幂等键
183	     * @param expectedVersion 解封单乐观锁版本
184	     * @param stepPercent    步进幅度，单位 %，0 &lt; step &le; 10
185	     * @return 已受理（或幂等重放的首次）任务
186	     */
187	    @Transactional
188	    public AdjustmentTask issueControlledAdjustment(long unsealId, String requestId,
189	                                                    int expectedVersion, BigDecimal stepPercent) {
190	        String fingerprint = Fingerprints.of("CADJ", requestId, String.valueOf(unsealId),
191	                String.valueOf(expectedVersion),
192	                stepPercent == null ? null : stepPercent.stripTrailingZeros().toPlainString());
193	        var existing = taskRepository.findByRequestId(requestId);
194	        if (existing.isPresent()) {
195	            return replayOrConflict(existing.get(), fingerprint);
196	        }
197	        if (stepPercent == null || stepPercent.compareTo(BigDecimal.ZERO) <= 0
198	                || stepPercent.compareTo(MAX_STEP_PERCENT) > 0) {
199	            throw new UnprocessableException("单次步进幅度须为 (0, 10]%，当前: " + stepPercent);
200	        }
201	        UnsealOrder order = unsealRepository.findById(unsealId)
202	                .orElseThrow(() -> new NotFoundException("解封单不存在: unsealId=" + unsealId));
203	        long valveId = order.valveId();
204	        Valve valveRef = valveRepository.findById(valveId)
205	                .orElseThrow(() -> new NotFoundException("阀门不存在: valveId=" + valveId));
206	        HeatingUnit unit = unitRepository.findById(valveRef.unitId())
207	                .orElseThrow(() -> new NotFoundException("单元不存在: unitId=" + valveRef.unitId()));
208	        // 锁顺序：station → valve → unseal，与复封/撤销/普通调节令一致，避免死锁。
209	        stationRepository.lockById(unit.stationId())
210	                .orElseThrow(() -> new NotFoundException("换热站不存在: stationId=" + unit.stationId()));
211	        Valve valve = valveRepository.lockById(valveRef.id()).orElseThrow();
212	        order = unsealRepository.lockById(unsealId).orElseThrow();
213	        // 持锁后重查幂等键：并发下同键请求在前序事务提交后按重放处理，不重复消费额度。
214	        var existingAfterLock = taskRepository.findByRequestId(requestId);
215	        if (existingAfterLock.isPresent()) {
216	            return replayOrConflict(existingAfterLock.get(), fingerprint);
217	        }
218	        if (order.status() != UnsealOrder.UnsealStatus.ACTIVE) {
219	            throw new UnprocessableException("解封单已撤销或已终结，禁止调节: unsealId=" + unsealId);
220	        }
221	        Instant now = clock.instant();
222	        if (now.isBefore(order.windowStart()) || !now.isBefore(order.windowEnd())) {
223	            throw new UnprocessableException("不在解封有效窗口内(UTC，半开区间): 窗口 "
224	                    + order.windowStart() + " ~ " + order.windowEnd() + ", 当前 " + now);
225	        }
226	        if (order.quotaUsed() >= order.quotaTotal()) {
227	            throw new UnprocessableException("解封调节额度已用尽: unsealId=" + unsealId);
228	        }
229	        if (order.version() != expectedVersion) {
230	            throw new ConflictException("解封单版本不一致: 当前=" + order.version()
231	                    + ", expectedVersion=" + expectedVersion);
232	        }
233	        int currentValveVersion = versionRepository.maxVersionNo(valve.id());
234	        if (currentValveVersion != order.valveVersion() + order.quotaUsed()) {
235	            throw new UnprocessableException("阀门开度版本与解封单不一致，禁止调节: 当前="
236	                    + currentValveVersion + ", 解封单引用=" + order.valveVersion()
237	                    + ", 已消费额度=" + order.quotaUsed());
238	        }
239	        long stationId = unit.stationId();
240	        long unitId = unit.id();
241	        if (taskRepository.existsActiveByStationId(stationId)) {
242	            throw new ConflictException("换热站存在执行中的调节任务，并发下达唯一受理: stationId=" + stationId);
243	        }
244	        int executed = taskRepository.countExecutedSince(unitId, now.minus(ADJUSTMENT_WINDOW));
245	        if (executed >= MAX_ADJUSTMENTS_PER_24H) {
246	            // 遵守 24 小时最多 3 次规则：转人工复核，不消费解封额度。
247	            AdjustmentTask review = new AdjustmentTask(0, stationId, unitId, requestId, fingerprint,
248	                    null, null, null, null, AdjustmentTask.TaskStatus.MANUAL_REVIEW,
249	                    null, null, null, now);
250	            return taskRepository.findById(taskRepository.insert(review)).orElseThrow();
251	        }
252	        BalanceService.BalanceView balance = balanceService.evaluateBalance(stationId, now);
253	        AdjustmentTask.ImbalanceType classification = balance.units().stream()
254	                .filter(u -> u.unitId() == unit.id())
255	                .map(BalanceService.UnitTemperature::classification)
256	                .findFirst()
257	                .orElseThrow(() -> new UnprocessableException(
258	                        "单元无温度数据或未失衡，无法判定调节方向: unitId=" + unitId));
259	        BigDecimal oldOpening = valve.openingPercent();
260	        BigDecimal newOpening = classification == AdjustmentTask.ImbalanceType.UNDERFLOW
261	                ? oldOpening.add(stepPercent) : oldOpening.subtract(stepPercent);
262	        if (newOpening.compareTo(BigDecimal.ZERO) < 0
263	                || newOpening.compareTo(new BigDecimal("100")) > 0) {
264	            throw new UnprocessableException("调节后开度越界 [0,100]%: " + newOpening);
265	        }
266	        AdjustmentTask task = new AdjustmentTask(0, stationId, unitId, requestId, fingerprint,
267	                classification, stepPercent, oldOpening, newOpening,
268	                AdjustmentTask.TaskStatus.EXECUTING, now, null, null, now);
269	        long taskId;
270	        try {
271	            taskId = taskRepository.insert(task);
272	        } catch (DuplicateKeyException e) {
273	            // 并发下同键插入：唯一约束保证只受理一次，重放首个结果且不重复消费额度。
274	            return taskRepository.findByRequestId(requestId)
275	                    .map(t -> replayOrConflict(t, fingerprint))
276	                    .orElseThrow(() -> e);
277	        }
278	        // 开度、版本与额度消费同事务提交，任一失败整体回滚，失败不消费额度。
279	        valveRepository.updateOpening(valve.id(), newOpening, now);
280	        versionRepository.insert(valve.id(), taskId, currentValveVersion + 1,
281	                oldOpening, newOpening, now);
282	        int consumed = unsealRepository.consumeQuota(unsealId, expectedVersion);
283	        if (consumed != 1) {
284	            throw new ConflictException("解封单并发变更，额度消费失败: unsealId=" + unsealId);
285	        }
286	        usageRepository.insert(unsealId, taskId, requestId, now);
287	        return taskRepository.findById(taskId).orElseThrow();
288	    }
289	
290	    /**
291	     * 效果评估：调节稳定满 4 小时（恰满允许）后执行，幂等键为 requestId。
292	     */
293	    @Transactional
294	    public Assessment assess(long taskId, String requestId) {
295	        String fingerprint = fingerprint("ASM", requestId, String.valueOf(taskId));
296	        var existing = assessmentRepository.findByRequestId(requestId);
297	        if (existing.isPresent()) {
298	            Assessment found = existing.get();
299	            if (!found.fingerprint().equals(fingerprint)) {
300	                throw new ConflictException("同键异参，返回 409: requestId=" + requestId);
301	            }
302	            return found;
303	        }
304	        AdjustmentTask task = taskRepository.findById(taskId)
305	                .orElseThrow(() -> new NotFoundException("调节任务不存在: taskId=" + taskId));
306	        switch (task.status()) {
307	            case EXECUTING -> {
308	                // 可评估
309	            }
310	            case ASSESSED -> throw new ConflictException("任务已评估: taskId=" + taskId);
311	            case ARCHIVED -> throw new ConflictException("任务已归档（终态），不允许评估: taskId=" + taskId);
312	            case MANUAL_REVIEW -> throw new ConflictException("任务已转人工复核，不允许评估: taskId=" + taskId);
313	            default -> throw new IllegalStateException("未知任务状态: " + task.status());
314	        }
315	        Instant now = clock.instant();
316	        Instant stabilizedAt = task.executedAt().plus(STABILIZATION);
317	        if (now.isBefore(stabilizedAt)) {
318	            throw new UnprocessableException("稳定期未满 4 小时，可评估时间(UTC): " + stabilizedAt);
319	        }
320	        BalanceService.BalanceView before = balanceService.evaluateBalance(
321	                task.stationId(), task.executedAt());
322	        BalanceService.BalanceView after = balanceService.evaluateBalance(task.stationId(), now);
323	        String detail = toJson(new Comparison(before, after));
324	        Assessment assessment = new Assessment(0, taskId, requestId, fingerprint,
325	                before.diff(), after.diff(), after.balanced(), detail, now);
326	        try {
327	            assessmentRepository.insert(assessment);
328	        } catch (DuplicateKeyException e) {
329	            return assessmentRepository.findByRequestId(requestId)
330	                    .filter(a -> a.fingerprint().equals(fingerprint))
331	                    .orElseThrow(() -> new ConflictException("同键异参，返回 409: requestId=" + requestId));
332	        }
333	        taskRepository.updateStatus(taskId, AdjustmentTask.TaskStatus.ASSESSED, now, null);
334	        return assessmentRepository.findByRequestId(requestId).orElseThrow();
335	    }
336	
337	    /**
338	     * 归档：评估归档为终态，重复归档返回幂等成功。
339	     */
340	    @Transactional
341	    public AdjustmentTask archive(long taskId) {
342	        AdjustmentTask task = taskRepository.findById(taskId)
343	                .orElseThrow(() -> new NotFoundException("调节任务不存在: taskId=" + taskId));
344	        switch (task.status()) {
345	            case ARCHIVED -> {
346	                return task;
347	            }
348	            case ASSESSED, MANUAL_REVIEW -> {
349	                taskRepository.updateStatus(taskId, AdjustmentTask.TaskStatus.ARCHIVED,
350	                        null, clock.instant());
351	                return taskRepository.findById(taskId).orElseThrow();
352	            }
353	            case EXECUTING -> throw new ConflictException("任务未评估，不允许归档: taskId=" + taskId);
354	            default -> throw new IllegalStateException("未知任务状态: " + task.status());
355	        }
356	    }
357	
358	    /**
359	     * 查询任务详情。
360	     */
361	    @Transactional(readOnly = true)
362	    public AdjustmentTask getTask(long taskId) {
363	        return taskRepository.findById(taskId)
364	                .orElseThrow(() -> new NotFoundException("调节任务不存在: taskId=" + taskId));
365	    }
366	
367	    /**
368	     * 查询任务的评估记录。
369	     */
370	    @Transactional(readOnly = true)
371	    public Assessment getAssessmentByTask(long taskId) {
372	        return assessmentRepository.findByTaskId(taskId)
373	                .orElseThrow(() -> new NotFoundException("任务尚未评估: taskId=" + taskId));
374	    }
375	
376	    /**
377	     * 查询单元阀门完整版本链，可复算开度变迁。
378	     */
