1	package com.example.starter.repository;
2	
3	import com.example.starter.domain.UnsealOrder;
4	import org.springframework.jdbc.core.JdbcTemplate;
5	import org.springframework.jdbc.core.RowMapper;
6	import org.springframework.jdbc.support.GeneratedKeyHolder;
7	import org.springframework.jdbc.support.KeyHolder;
8	import org.springframework.stereotype.Repository;
9	
10	import java.sql.PreparedStatement;
11	import java.sql.Statement;
12	import java.sql.Timestamp;
13	import java.time.Instant;
14	import java.util.Optional;
15	
16	/**
17	 * 临时解封单数据访问。
18	 */
19	@Repository
20	public class UnsealOrderRepository {
21	
22	    private static final RowMapper<UnsealOrder> MAPPER = (rs, n) -> new UnsealOrder(
23	            rs.getLong("id"), rs.getLong("seal_id"), rs.getLong("valve_id"),
24	            rs.getString("seal_no"), rs.getInt("valve_version"),
25	            rs.getString("approver_a"), rs.getString("approver_b"),
26	            rs.getTimestamp("window_start").toInstant(),
27	            rs.getTimestamp("window_end").toInstant(),
28	            rs.getInt("quota_total"), rs.getInt("quota_used"),
29	            UnsealOrder.UnsealStatus.valueOf(rs.getString("status")),
30	            rs.getInt("version"),
31	            rs.getTimestamp("created_at").toInstant(),
32	            Optional.ofNullable(rs.getTimestamp("revoked_at")).map(Timestamp::toInstant).orElse(null),
33	            rs.getString("request_id"), rs.getString("fingerprint"),
34	            rs.getString("revoke_request_id"), rs.getString("revoke_fingerprint"));
35	
36	    private static final String COLUMNS = "id, seal_id, valve_id, seal_no, valve_version,"
37	            + " approver_a, approver_b, window_start, window_end, quota_total, quota_used,"
38	            + " status, version, created_at, revoked_at, request_id, fingerprint,"
39	            + " revoke_request_id, revoke_fingerprint";
40	
41	    private final JdbcTemplate jdbc;
42	
43	    public UnsealOrderRepository(JdbcTemplate jdbc) {
44	        this.jdbc = jdbc;
45	    }
46	
47	    /**
48	     * 插入解封单并返回生成的主键。
49	     */
50	    public long insert(UnsealOrder order) {
51	        KeyHolder keys = new GeneratedKeyHolder();
52	        jdbc.update(con -> {
53	            PreparedStatement ps = con.prepareStatement("INSERT INTO unseal_order"
54	                            + " (seal_id, valve_id, seal_no, valve_version, approver_a, approver_b,"
55	                            + " window_start, window_end, quota_total, quota_used, status, version,"
56	                            + " created_at, revoked_at, request_id, fingerprint)"
57	                            + " VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
58	                    Statement.RETURN_GENERATED_KEYS);
59	            ps.setLong(1, order.sealId());
60	            ps.setLong(2, order.valveId());
61	            ps.setString(3, order.sealNo());
62	            ps.setInt(4, order.valveVersion());
63	            ps.setString(5, order.approverA());
64	            ps.setString(6, order.approverB());
65	            ps.setTimestamp(7, Timestamp.from(order.windowStart()));
66	            ps.setTimestamp(8, Timestamp.from(order.windowEnd()));
67	            ps.setInt(9, order.quotaTotal());
68	            ps.setInt(10, order.quotaUsed());
69	            ps.setString(11, order.status().name());
70	            ps.setInt(12, order.version());
71	            ps.setTimestamp(13, Timestamp.from(order.createdAt()));
72	            ps.setTimestamp(14, order.revokedAt() == null ? null : Timestamp.from(order.revokedAt()));
73	            ps.setString(15, order.requestId());
74	            ps.setString(16, order.fingerprint());
75	            return ps;
76	        }, keys);
77	        return keys.getKey().longValue();
78	    }
79	
80	    /**
81	     * 按 ID 查询解封单。
82	     */
83	    public Optional<UnsealOrder> findById(long id) {
84	        return jdbc.query("SELECT " + COLUMNS + " FROM unseal_order WHERE id = ?", MAPPER, id)
85	                .stream().findFirst();
86	    }
87	
88	    /**
89	     * 按 ID 查询并加行级写锁（SELECT ... FOR UPDATE），用于撤销与受控调节的重查串行化。
90	     */
91	    public Optional<UnsealOrder> lockById(long id) {
92	        return jdbc.query("SELECT " + COLUMNS + " FROM unseal_order WHERE id = ? FOR UPDATE",
93	                MAPPER, id).stream().findFirst();
94	    }
95	
96	    /**
97	     * 按批准幂等键查询解封单。
98	     */
99	    public Optional<UnsealOrder> findByRequestId(String requestId) {
100	        return jdbc.query("SELECT " + COLUMNS + " FROM unseal_order WHERE request_id = ?",
101	                MAPPER, requestId).stream().findFirst();
102	    }
103	
104	    /**
105	     * 查询铅封当前有效（ACTIVE）的解封单，无则空。
106	     */
107	    public Optional<UnsealOrder> findActiveBySealId(long sealId) {
108	        return jdbc.query("SELECT " + COLUMNS + " FROM unseal_order"
109	                        + " WHERE seal_id = ? AND status = 'ACTIVE'",
110	                MAPPER, sealId).stream().findFirst();
111	    }
112	
113	    /**
114	     * 原子消费一次额度：仅当版本一致、仍 ACTIVE 且额度足够时生效，返回更新行数。
115	     */
116	    public int consumeQuota(long id, int expectedVersion) {
117	        return jdbc.update("UPDATE unseal_order SET quota_used = quota_used + 1,"
118	                        + " version = version + 1"
119	                        + " WHERE id = ? AND version = ? AND status = 'ACTIVE'"
120	                        + " AND quota_used < quota_total",
121	                id, expectedVersion);
122	    }
123	
124	    /**
125	     * 原子撤销：仅当版本一致且仍 ACTIVE 时生效，返回更新行数。
126	     */
127	    public int revoke(long id, int expectedVersion, Instant revokedAt,
128	                      String revokeRequestId, String revokeFingerprint) {
129	        return jdbc.update("UPDATE unseal_order SET status = 'REVOKED', revoked_at = ?,"
130	                        + " version = version + 1, revoke_request_id = ?, revoke_fingerprint = ?"
131	                        + " WHERE id = ? AND version = ? AND status = 'ACTIVE'",
132	                Timestamp.from(revokedAt), revokeRequestId, revokeFingerprint, id, expectedVersion);
133	    }
134	
135	    /**
136	     * 复封时原子终结铅封下仍有效的解封单，返回更新行数。
137	     */
