27	@RestController
28	@RequestMapping("/api")
29	public class SealController {
30	
31	    private final SealService sealService;
32	    private final AdjustmentService adjustmentService;
33	
34	    public SealController(SealService sealService, AdjustmentService adjustmentService) {
35	        this.sealService = sealService;
36	        this.adjustmentService = adjustmentService;
37	    }
38	
39	    /**
40	     * 铅封登记请求。
41	     *
42	     * @param requestId    客户端幂等键
43	     * @param sealNo       铅封号，全局唯一
44	     * @param valveVersion 登记时核对的开度版本（无版本为 0）
45	     */
46	    public record SealRegisterRequest(@NotBlank String requestId, @NotBlank String sealNo,
47	                                      @NotNull Integer valveVersion) {
48	    }
49	
50	    /**
51	     * 临时解封批准请求。
52	     *
53	     * @param requestId       客户端幂等键
54	     * @param expectedVersion 铅封乐观锁版本
55	     * @param valveVersion    引用的阀门开度版本
56	     * @param approverA       授权人甲，须与授权人乙不同
57	     * @param approverB       授权人乙，须与授权人甲不同
58	     * @param windowStart     有效窗口起点（UTC，半开区间，含）
59	     * @param windowEnd       有效窗口终点（UTC，半开区间，不含）
60	     */
61	    public record UnsealApproveRequest(@NotBlank String requestId, @NotNull Integer expectedVersion,
62	                                       @NotNull Integer valveVersion,
63	                                       @NotBlank String approverA, @NotBlank String approverB,
64	                                       @NotNull Instant windowStart, @NotNull Instant windowEnd) {
65	    }
66	
67	    /**
68	     * 解封撤销请求。
69	     *
70	     * @param requestId       客户端幂等键
71	     * @param expectedVersion 解封单乐观锁版本
72	     */
73	    public record UnsealRevokeRequest(@NotBlank String requestId, @NotNull Integer expectedVersion) {
74	    }
75	
76	    /**
77	     * 复封请求。
78	     *
79	     * @param requestId       客户端幂等键
80	     * @param expectedVersion 当前完整铅封的乐观锁版本
81	     * @param newSealNo       新铅封号，全局唯一
82	     * @param checkerA        核对人甲，须与核对人乙不同
83	     * @param checkerB        核对人乙，须与核对人甲不同
84	     * @param valveVersion    核对的当前开度版本
85	     */
86	    public record ResealRequest(@NotBlank String requestId, @NotNull Integer expectedVersion,
87	                                @NotBlank String newSealNo,
88	                                @NotBlank String checkerA, @NotBlank String checkerB,
89	                                @NotNull Integer valveVersion) {
90	    }
91	
92	    /**
93	     * 受控调节请求。
94	     *
95	     * @param requestId       客户端幂等键
96	     * @param expectedVersion 解封单乐观锁版本
97	     * @param stepPercent     步进幅度，单位 %，(0, 10]，越界由服务层返回 422
98	     */
99	    public record ControlledAdjustmentRequest(@NotBlank String requestId,
100	                                              @NotNull Integer expectedVersion,
101	                                              @NotNull BigDecimal stepPercent) {
102	    }
103	
104	    /**
105	     * 铅封登记：登记唯一铅封号、当前开度版本与封存时刻。
106	     */
107	    @PostMapping("/valves/{valveId}/seals")
108	    public ValveSeal registerSeal(@PathVariable long valveId,
109	                                  @Valid @RequestBody SealRegisterRequest request) {
110	        return sealService.registerSeal(valveId, request.requestId(),
111	                request.sealNo(), request.valveVersion());
112	    }
113	
114	    /**
