132	     */
133	    @PostMapping("/valves/{valveId}/reseals")
134	    public ValveSeal reseal(@PathVariable long valveId,
135	                            @Valid @RequestBody ResealRequest request) {
136	        return sealService.reseal(valveId, request.requestId(), request.expectedVersion(),
137	                request.newSealNo(), request.checkerA(), request.checkerB(), request.valveVersion());
138	    }
