156	        return sealService.getUnseal(unsealId);
157	    }
158	
159	    /**
160	     * 撤销解封单：仅禁止新调节，不回拨已改开度。
161	     */
162	    @PostMapping("/unseals/{unsealId}/revoke")
163	    public UnsealOrder revokeUnseal(@PathVariable long unsealId,
164	                                    @Valid @RequestBody UnsealRevokeRequest request) {
165	        return sealService.revokeUnseal(unsealId, request.requestId(), request.expectedVersion());
166	    }
167	
168	    /**
169	     * 受控调节：解封窗口与额度内下达调节令，原子更新开度、写版本并消费一次额度。
170	     */
171	    @PostMapping("/unseals/{unsealId}/adjustments")
172	    public AdjustmentTask controlledAdjust(@PathVariable long unsealId,
