10	import java.util.Map;
11	
12	/**
13	 * 统一错误语义：业务异常映射为对应 HTTP 状态码与 JSON 错误体。
14	 */
15	@RestControllerAdvice
16	public class ApiExceptionHandler {
17	
18	    /**
19	     * 业务异常：404/409/422。
20	     */
21	    @ExceptionHandler(BusinessException.class)
22	    public ResponseEntity<Map<String, Object>> business(BusinessException e) {
23	        return ResponseEntity.status(e.status())
24	                .body(Map.of("error", e.getClass().getSimpleName(), "message", e.getMessage()));
25	    }
26	
27	    /**
28	     * 参数校验失败：400。
29	     */
30	    @ExceptionHandler(MethodArgumentNotValidException.class)
31	    public ResponseEntity<Map<String, Object>> validation(MethodArgumentNotValidException e) {
32	        String message = e.getBindingResult().getFieldErrors().stream()
33	                .map(f -> f.getField() + " " + f.getDefaultMessage())
34	                .findFirst().orElse("参数校验失败");
35	        return ResponseEntity.status(HttpStatus.BAD_REQUEST)
36	                .body(Map.of("error", "ValidationException", "message", message));
37	    }
38	}
