    /**
     * 查询解封单的额度消费轨迹，按主键升序。
     */
    public List<UnsealQuotaUsage> findByUnsealId(long unsealId) {
        return jdbc.query("SELECT id, unseal_id, task_id, request_id, used_at"
                + " FROM unseal_quota_usage WHERE unseal_id = ? ORDER BY id", MAPPER, unsealId);
    }
