/**
 * HTTP 主流程：温度上报 → 失衡判定 → 步进调节 → 稳定 4 小时 → 效果评估 → 归档。
 */
@AutoConfigureMockMvc
class ApiFlowTest extends IntegrationTestBase {

    @Autowired
