        assertThat(openingOf(2L)).isEqualByComparingTo(new BigDecimal("50.00"));
        assertThat(sealService.getUnseal(order1.id()).quotaUsed()).isEqualTo(1);
        assertThat(sealService.getUnseal(order2.id()).quotaUsed()).isEqualTo(1);
